# -*- coding: utf-8 -*-
REF_OLD = r"Найдите производную функции в любой точке: $x \in \mathbb{R}$, используя задание $4.12$: "
REF_NEW = r"Найдите производную функции в любой точке $x \in \mathbb{R}$ (используйте, что $(x^{3})'=3x^{2}$): "
REF_WHY = r"условие ссылалось на «задание 4.12», которое ученик не видит; ссылка заменена самим фактом из задания 4.12: $(x^{3})'=3x^{2}$"
for t in ["G11_TB_§4_4_18_а","G11_TB_§4_4_18_б","G11_TB_§4_4_18_в","G11_TB_§4_4_18_г","G11_TB_§4_4_18_д","G11_TB_§4_4_18_е","G11_TB_§4_4_18_ж","G11_TB_§4_4_18_з","G11_TB_§4_4_19_а","G11_TB_§4_4_19_б"]:
    E(t, REF_WHY, qrep=(REF_OLD, REF_NEW))
E("G11_TB_4_3*_4_19_г", REF_WHY + r"; добавлен третий неверный вариант; ключ $3(x+1)^{2}=3x^{2}+6x+3$ верен", qrep=(REF_OLD, REF_NEW),
  dadd=[(r"$3x^{2}$", r"Ученик продифференцировал только старший член $x^{3}$ разложения $(x+1)^{3}=x^{3}+3x^{2}+3x+1$ и потерял остальные слагаемые.")])
E("G11_TB_§4_4_19_в", REF_WHY + r"; добавлен третий неверный вариант; ключ $2(3x+1)\cdot3=18x+6$ верен", qrep=(REF_OLD, REF_NEW),
  dadd=[(r"$9x^{2}+6x+1$", r"Ученик раскрыл квадрат $(3x+1)^{2}$, но не продифференцировал результат.")])
E("G11_TB_§4_4_19_д", REF_WHY + r"; добавлен третий неверный вариант; ключ $3(x-2)^{2}=3x^{2}-12x+12$ верен", qrep=(REF_OLD, REF_NEW),
  dadd=[(r"$3x^{2}+12x+12$", r"Ученик ошибся в знаке: $3(x-2)^{2}=3x^{2}-12x+12$, а не $3(x+2)^{2}$.")])
E("G11_TB_§4_4_19_е", REF_WHY + r"; добавлен третий неверный вариант; ключ $3(2x+3)^{2}\cdot2=24x^{2}+72x+54$ верен", qrep=(REF_OLD, REF_NEW),
  dadd=[(r"$8x^{3}+36x^{2}+54x+27$", r"Ученик раскрыл куб $(2x+3)^{3}$, но не продифференцировал результат.")])
SN = r"Отрезок $[0; 1]$ разделён на $n$ равных частей, и в качестве интегральной суммы функции $f$ взята сумма $S_{n}=f(0)\cdot\dfrac{1}{n}+f\left(\dfrac{1}{n}\right)\cdot\dfrac{1}{n}+\ldots+f\left(\dfrac{n-1}{n}\right)\cdot\dfrac{1}{n}$. "
E("G11_TB_6_4_6_28_1", r"вопрос сравнивал суммы «в заданиях 6.27 и 6.28», которых ученик не видит, а номер «6.28» был превращён в десятичную дробь «6,28»; обе суммы выписаны в условии",
  q=SN + r"Чем отличаются такие суммы для функций $y=x$ и $y=-x$?",
  k=r"Для $y=-x$ все слагаемые неположительны, и сумма равна сумме для $y=x$, взятой с противоположным знаком",
  dnew={0: (r"Для $y=-x$ все слагаемые положительны, и суммы равны", r"Ученик не учёл знак: $f\left(\dfrac{k}{n}\right)=-\dfrac{k}{n}\le0$, поэтому каждое слагаемое меняет знак."),
        1: (r"Для $y=-x$ слагаемые разных знаков, и сумма равна нулю", r"Ученик решил, что знаки чередуются; но все значения $-\dfrac{k}{n}$ при $k\ge0$ неположительны."),
        2: (r"Для $y=-x$ сумма содержит меньше слагаемых", r"Ученик решил, что число слагаемых зависит от функции; в обеих суммах по $n$ слагаемых, различаются только их знаки.")})
E("G11_TB_6_4_6_29_1", r"условие ссылалось на «план задания 6.27», которого ученик не видит; способ составления суммы выписан в условии; ключ пересчитан: $S_{1}=1$, $S_{2}=\frac{5}{4}$, $S_{3}=\frac{4}{3}$, $S_{4}=\frac{11}{8}$",
  q=SN + r"Вычислите $S_{1}$, $S_{2}$, $S_{3}$, $S_{4}$ для функции $f(x)=x+1$.")
E("G11_TB_6_4_6_29_2", r"в условии не было указано, о какой функции и какой сумме идёт речь; ключ $\frac{3}{2}$ верен: $S_{n}=1+\frac{n-1}{2n}\to\frac{3}{2}$",
  q=SN + r"Существует ли предел $S_{n}$ при $n\to+\infty$ для функции $f(x)=x+1$? Если да, то чему он равен?")
E("G5_TB_28_491", r"в условии «коробка с клеем $-10000$ сум» тире стало знаком минус; ключ записан без разделителей разрядов; ключ верен: $42:8=5{,}25\to6$ коробок, $42\cdot70\,000+6\cdot10\,000=3\,000\,000$",
  qrep=(r"а коробка с клеем $-10000$ сум", r"а коробка с клеем — $10\,000$ сум"), k=r"$6$ коробок, $3\,000\,000$ сум")
E("G5_TB_28_490", r"ключ записан без разделителя разрядов; ключ верен: $64\cdot0{,}2=12{,}8$ кг, $12{,}8:2=6{,}4\to7$ банок, $7\cdot80\,000=560\,000$",
  k=r"$7$ банок, $560\,000$ сум", dval={2: r"$13$ банок, $1\,040\,000$ сум"})
BETW = "в формате выбора ответа вопрос «найдите какое-нибудь значение» допускал несколько верных вариантов, один вариант был испорчен («$0.1.5$»); вопрос переформулирован, все неверные варианты лежат вне промежутка"
E("G5_TB_31_1183.2", BETW, q=r"Какое из чисел удовлетворяет неравенству $0{,}1<x<0{,}2$?",
  dnew={0: (r"$0{,}25$", r"Ученик не сравнил с правой границей: $0{,}25>0{,}2$."), 1: (r"$0{,}015$", r"Ученик сравнил числа по количеству цифр: $0{,}015<0{,}1$, так как $0{,}015<0{,}100$."), 2: (r"$0{,}2$", r"Ученик не учёл, что неравенство строгое: $x=0{,}2$ не меньше $0{,}2$.")})
E("G5_TB_31_1183.6", BETW.replace("$0.1.5$", "$0.12.5$"), q=r"Какое из чисел удовлетворяет неравенству $0{,}12<x<0{,}13$?",
  dnew={0: (r"$0{,}13$", r"Ученик не учёл, что неравенство строгое: $x=0{,}13$ не меньше $0{,}13$."), 1: (r"$0{,}14$", r"Ученик не сравнил с правой границей: $0{,}14>0{,}13$."), 2: (r"$0{,}1$", r"Ученик не сравнил с левой границей: $0{,}1<0{,}12$.")})
E("G6_TB_25_1012.3", BETW.replace("$0.1.5$", "$0.1650.17$"), q=r"Какое из чисел меньше $0{,}17$, но больше $0{,}16$?",
  dnew={0: (r"$0{,}17$", r"Ученик не учёл, что число должно быть строго меньше $0{,}17$."), 1: (r"$1{,}65$", r"Ученик потерял ноль в целой части: $1{,}65>0{,}17$."), 2: (r"$0{,}0165$", r"Ученик поставил лишний ноль после запятой: $0{,}0165<0{,}16$.")})
E("G8_TB_10_270", r"в ключе периодическая дробь $-2{,}(3)$ была разорвана на «$-2$» и «$(3)$», а $0{,}818118111\ldots$ записано с точкой; классификация верна: иррациональны только $0{,}818118111\ldots$ и $\pi$",
  k=r"Рациональные: $\dfrac{1}{7}$, $0$, $0{,}25$, $-2{,}(3)$, $4{,}2(51)$, $217$. Иррациональные: $0{,}818118111\ldots$, $\pi$",
  dnew={0: (r"Рациональные: $\dfrac{1}{7}$, $0{,}25$, $217$. Иррациональные: $0$, $-2{,}(3)$, $0{,}818118111\ldots$, $4{,}2(51)$, $\pi$", r"Ученик отнёс к иррациональным ноль и периодические дроби; но $0=\dfrac{0}{1}$, а любая периодическая дробь — рациональное число."),
        1: (r"Рациональные: $\dfrac{1}{7}$, $0$, $0{,}25$, $-2{,}(3)$, $4{,}2(51)$, $217$, $0{,}818118111\ldots$. Иррациональные: $\pi$", r"Ученик решил, что дробь $0{,}818118111\ldots$ периодическая; но число единиц между восьмёрками растёт, периода нет — число иррационально."),
        2: (r"Рациональные: $0$, $0{,}25$, $217$. Иррациональные: $\dfrac{1}{7}$, $-2{,}(3)$, $0{,}818118111\ldots$, $4{,}2(51)$, $\pi$", r"Ученик отнёс к иррациональным бесконечные периодические дроби ($\dfrac{1}{7}=0{,}(142857)$); они рациональны.")})
E("G9_TB_1_9_4", r"в ключе десятичные дроби записаны с точкой; равенство верно: $\frac{52}{15}=3{,}4666\ldots=3{,}4(6)$",
  k=r"$3\dfrac{7}{15}=\dfrac{52}{15}=3{,}4666\ldots=3{,}4(6)$")
E("G9_TB_30_609", r"ключ записан с точкой; ключ верен: $P_{1}=48$ см, $P_{8}=\frac{48}{2^{7}}=0{,}375$ см", k=r"$0{,}375$")
E("G9_TB_32_400", r"ключ записан с точкой; ключ верен: $S_{1}=16$ см$^{2}$, $S_{7}=\frac{16}{2^{6}}=0{,}25$ см$^{2}$", k=r"$0{,}25$")
